def pair(en, zh):
    return '<span class="bi"><span class="bi-en" lang="en">' + en + '</span><span class="bi-zh" lang="zh-Hans">' + zh + '</span></span>'

def shell(title, description, path, body):
    nav = ''.join(f'<a href="{url}"'+(' aria-current="page"' if url == path else '')+f'>{pair(label, zh)}</a>'
                  for url,label,zh in [('/', 'Overview','项目介绍'),('/demo/','Try the demo','体验演示'),('/privacy/','Privacy','隐私'),('/terms/','Terms','条款')])
