ZH_HEADINGS={'Privacy policy':'隐私政策','Terms of use':'使用条款','1. The project and this website':'1. 项目和公开网站','2. Information in the separate local application':'2. 独立本机应用的资料','3. Google information and Gmail permissions':'3. Google 资料与 Gmail 权限','4. Authorization credentials and automatic refresh':'4. 凭据与自动刷新','5. Other services and AI processing':'5. 其他服务与 AI 处理','6. Google API Limited Use':'6. Google API 限制使用','7. Retention, disconnection and deletion':'7. 保留、断开和删除','8. Contact and policy changes':'8. 联系与政策更新','1. Intended use':'1. 使用目的','2. Owner review and purchasing':'2. 人工核对与采购','3. Accounts, credentials and services':'3. 账户、凭据和服务','4. Availability and limitations':'4. 可用性与限制','5. Privacy and access control':'5. 隐私与访问控制','6. Responsible use and changes':'6. 负责任使用与变更','7. Contact':'7. 联系','Project information':'项目信息','Clear information for informed authorization.':'授权前，清楚了解资料用途。'}
def public_locales(body):
    def block(match):
        tag, attrs, content=match.group(1),match.group(2),match.group(3)
        plain=unescape(re.sub('<[^>]+>', ' ', content));plain=' '.join(plain.split())
        if re.search('[\u3400-\u9fff]', plain):
            if 'class="' in attrs:attrs=attrs.replace('class="','class="locale-zh ',1)
            else:attrs+=' class="locale-zh"'
            return f'<{tag}{attrs}>{content}</{tag}>'
        zh=ZH_HEADINGS.get(plain) or next((value for prefix,value in ZH_COPY if plain.startswith(prefix)),None)
        if not zh:return match.group(0)
        return f'<{tag}{attrs}>{pair(content,escape(zh))}</{tag}>'
    body=re.sub(r'<(h[123]|p)([^>]*)>(.*?)</\1>',block,body,flags=re.S)
    for english,chinese in [('Try your own demo café ↗','体验你的模拟咖啡店 ↗'),('How your data is used','资料如何使用'),('Read the complete privacy policy →','阅读完整隐私政策 →'),('Gmail is optional','本机 Gmail 可选功能'),('Only the necessary Google permission','只请求所需 Google 权限'),('You can disconnect','可随时断开连接')]:
        body=body.replace('>'+english+'<','>'+pair(english,chinese)+'<')
    for english,chinese in [('TOMORROW’S PREPARATION','明日备货'),('Ready for your review','等待你核对'),('Illustrative demo','模拟示例'),('Weather context','天气情景'),('Rain may change demand','降雨可能影响需求'),('Calendar context','日历情景'),('Check local holidays','核对当地假日'),('Ingredient','食材'),('Suggested packs','建议包装'),('Fresh milk','鲜奶'),('15 boxes','15 盒'),('Oat milk','燕麦奶'),('7 cartons','7 盒'),('Coffee beans','咖啡豆'),('3 bags','3 袋'),('Weather &amp; holiday context','天气与假日情景'),('Owner review before procurement','采购前人工核对'),('Supplier drafts, ready to check','供应商草稿，先核对再发送')]:
        body=body.replace('>'+english+'<','>'+pair(english,chinese)+'<')
    body=body.replace('Review quantities → Approve the list → Create supplier drafts<br>Example quantities only. No live purchasing takes place on this website.',pair('Review quantities → Approve the list → Create supplier drafts<br>Example quantities only. No live purchasing takes place on this website.','核对数量 → 批准清单 → 生成供应商草稿。仅为示例数量，网站不会真实下单。'))
    body=body.replace('<div class="notice" lang="zh-CN">','<div class="notice locale-zh" lang="zh-Hans">')
    return body
home=public_locales(home);privacy=public_locales(privacy);terms=public_locales(terms)

def four_languages(en, zh, ms, es):
    return '<span class="bi" data-language-fixed="true">' + ''.join(
        f'<span class="bi-{code}" lang="{lang}">{escape(text)}</span>'
        for code, lang, text in [('en','en',en),('zh','zh-Hans',zh),('ms','ms',ms),('es','es',es)]
    ) + '</span>'

