home, privacy, terms = update_cloud_disclosures(home, privacy, terms, four_languages)

import json
public_config=json.loads((BASE/'public-config.json').read_text(encoding='utf-8'))
gmail_client=public_config.get('gmailClientId','')
if not re.fullmatch(r'[0-9]+-[A-Za-z0-9_-]+[.]apps[.]googleusercontent[.]com',gmail_client):
    raise ValueError('Invalid public Gmail client ID')
(BASE/'dist'/'demo'/'public-config.js').write_text('export const PUBLIC_GMAIL_CLIENT_ID = '+json.dumps(gmail_client)+';\n',encoding='utf-8')

pages = {'index.html': shell('A calmer close', 'Cafe Replenishment helps café owners explore weather, simulated inventory, approval and downloadable supplier drafts.', '/', home),
         'privacy/index.html': document('Privacy policy', 'How Cafe Replenishment uses and protects local and Google information.', '/privacy/', privacy),
         'terms/index.html': document('Terms of use', 'Intended use and limitations of the Cafe Replenishment demonstration.', '/terms/', terms),
         'demo/index.html': (BASE / 'demo_page.html').read_text(encoding='utf-8').replace('{{CANONICAL_URL}}', escape(SITE_ORIGIN + '/demo/', quote=True))}
for name, html in pages.items():
    path = BASE / 'dist' / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(html, encoding='utf-8')
(BASE / 'dist' / 'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: ' + SITE_ORIGIN + '/sitemap.xml\n', encoding='utf-8')
sitemap = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + ''.join('<url><loc>' + escape(SITE_ORIGIN + path) + '</loc></url>' for path in ('/', '/demo/', '/privacy/', '/terms/')) + '</urlset>\n'
(BASE / 'dist' / 'sitemap.xml').write_text(sitemap, encoding='utf-8')
redirects=BASE/'dist'/'_redirects'
if SITE_ORIGIN == 'https://www.cafe-replenishment-demo.com':
    redirects.write_text('http://deluxe-chimera-c9f59e.netlify.app/* https://www.cafe-replenishment-demo.com/:splat 301!\nhttps://deluxe-chimera-c9f59e.netlify.app/* https://www.cafe-replenishment-demo.com/:splat 301!\n',encoding='utf-8')
elif redirects.exists():
    redirects.unlink()
print('Built 4 public pages, sitemap and robots. No application runtime or credentials were accessed.')
